import numpy as np
def f(inp):
    inp=np.array(inp); vals,counts=np.unique(inp,return_counts=True); bg=vals[np.argmax(counts)]
    pos=np.argwhere(inp!=bg)
    r0,r1=pos[:,0].min(),pos[:,0].max(); c0,c1=pos[:,1].min(),pos[:,1].max()
    tile=inp[r0:r1+1,c0:c1+1]; n=tile.shape[0]
    O=np.zeros((2*n,2*n),int)
    for i in range(2*n):
        for j in range(2*n):
            O[i,j]=tile[i%n,j%n]
    return O.tolist()
