import numpy as np
def dihedral(M):
    res={}
    res['id']=M; res['ud']=M[::-1,:]; res['lr']=M[:,::-1]; res['udlr']=M[::-1,::-1]
    r=np.rot90(M,1)
    res['r90']=r; res['r270']=np.rot90(M,3); res['T']=M.T; res['antiT']=np.fliplr(M.T)
    return res
def fit(Q,tile,H,W):
    res=[]
    for name,Mt in dihedral(tile).items():
        h,w=Mt.shape
        hits=[]
        for a in range(h):
            for b in range(w):
                ok=all(Q[u,v]==Mt[(u+a)%h][(v+b)%w] for u in range(H) for v in range(W))
                if ok: hits.append((a,b))
        if hits: res.append((name,hits))
    return res
